const NORMAL = hmUI.show_level.ONLY_NORMAL
const AOD = hmUI.show_level.ONLY_AOD
const TICK_MS = 100

function img(x, y, src, show_level = NORMAL) {
  return hmUI.createWidget(hmUI.widget.IMG, { x, y, src, show_level })
}

function value(pos, font, type, extra = {}) {
  const [x, y, w] = pos
  const opts = {
    x,
    y,
    w,
    font_array: font,
    h_space: L.valSpace,
    align_h: hmUI.align.CENTER_H,
    padding: false,
    show_level: NORMAL
  }
  if (type !== undefined) opts.type = type
  return hmUI.createWidget(hmUI.widget.TEXT_IMG, Object.assign(opts, extra))
}

// Total sleep as decimal hours, "7.3" for 7h15: same as Retro
function sleepHours(widget) {
  const sensor = hmSensor.createSensor(hmSensor.id.SLEEP)
  const update = () => {
    if (sensor.updateInfo) sensor.updateInfo()
    const minutes = sensor.getTotalTime() || 0
    widget.setProperty(hmUI.prop.TEXT, (Math.round(minutes / 6) / 10).toFixed(1))
  }
  update()
  hmUI.createWidget(hmUI.widget.WIDGET_DELEGATE, { resume_call: update })
}

function status(pos, src, type) {
  hmUI.createWidget(hmUI.widget.IMG_STATUS, { x: pos[0], y: pos[1], src, type, show_level: NORMAL })
}

function click(rect, type) {
  const [x, y, w, h] = rect
  hmUI.createWidget(hmUI.widget.IMG_CLICK, { x, y, w, h, type, show_level: NORMAL })
}

function time(digits, secDigits, show_level, hourAt, minuteAt, secondAt) {
  const opts = {
    hour_zero: 1,
    hour_startX: hourAt[0],
    hour_startY: hourAt[1],
    hour_array: digits,
    hour_space: L.cellSpace,
    hour_align: hmUI.align.LEFT,
    minute_zero: 1,
    minute_startX: minuteAt[0],
    minute_startY: minuteAt[1],
    minute_array: digits,
    minute_space: L.cellSpace,
    minute_align: hmUI.align.LEFT,
    minute_follow: 0,
    show_level
  }
  if (secDigits) {
    Object.assign(opts, {
      second_zero: 1,
      second_startX: secondAt[0],
      second_startY: secondAt[1],
      second_array: secDigits,
      second_space: L.cellSpace,
      second_align: hmUI.align.LEFT,
      second_follow: 0
    })
  }
  hmUI.createWidget(hmUI.widget.IMG_TIME, opts)
}

function date(digits, slashSrc, weekImgs, show_level, P) {
  hmUI.createWidget(hmUI.widget.IMG_DATE, {
    day_startX: P.day[0],
    day_startY: P.day[1],
    day_en_array: digits,
    day_sc_array: digits,
    day_tc_array: digits,
    day_zero: 1,
    day_space: L.dateSpace,
    day_align: hmUI.align.LEFT,
    day_is_character: false,
    month_startX: P.slash[0] + L.slashW + 4,
    month_startY: P.day[1],
    month_en_array: digits,
    month_sc_array: digits,
    month_tc_array: digits,
    month_zero: 1,
    month_space: L.dateSpace,
    month_align: hmUI.align.LEFT,
    month_is_character: false,
    month_follow: 0,
    show_level
  })
  img(P.slash[0], P.slash[1], slashSrc, show_level)
  hmUI.createWidget(hmUI.widget.IMG_WEEK, {
    x: P.week[0],
    y: P.week[1],
    week_en: weekImgs,
    week_sc: weekImgs,
    week_tc: weekImgs,
    show_level
  })
}

// The wheels sit on top of a plain IMG_TIME: if the timer never runs they stay
// hidden and the face is still a correct, just motionless, clock.
function odometer() {
  const C = L.cells
  time(F.black, F.red, NORMAL, C[0], C[2], C[4])

  const wheels = C.map(([x, y], i) => {
    const widget = img(x, y, F.black[0])
    widget.setProperty(hmUI.prop.VISIBLE, false)
    return {
      widget, x, y,
      digits: i < 4 ? F.black : F.red,
      rolls: i < 4 ? F.black_roll : F.red_roll,
      from: -1, to: -1, step: 0, src: ''
    }
  })
  const clock = hmSensor.createSensor(hmSensor.id.TIME)
  let id = null

  function show(w, src) {
    if (src === w.src) return
    if (!w.src) w.widget.setProperty(hmUI.prop.VISIBLE, true)
    w.src = src
    w.widget.setProperty(hmUI.prop.MORE, { x: w.x, y: w.y, src })
  }

  function tick() {
    const h = clock.format_hour
    const now = [h / 10 | 0, h % 10, clock.minute / 10 | 0, clock.minute % 10,
                 clock.second / 10 | 0, clock.second % 10]
    wheels.forEach((w, i) => {
      if (w.to !== now[i]) {
        w.from = w.to
        w.to = now[i]
        w.step = 0
      }
      const roll = w.rolls[`${w.from}${w.to}`]  // none for a jump: just snap
      show(w, roll && w.step < roll.length ? roll[w.step++] : w.digits[w.to])
    })
  }

  function start() {
    if (id !== null || hmSetting.getScreenType() === hmSetting.screen_type.AOD) return
    wheels.forEach(w => { w.to = -1 })  // time moved while paused: snap, don't replay
    id = timer.createTimer(0, TICK_MS, tick)
  }

  function stop() {
    if (id === null) return
    timer.stopTimer(id)
    id = null
  }

  start()
  hmUI.createWidget(hmUI.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop })
}

WatchFace({
  build() {
    const T = hmUI.data_type
    // hmSetting.getLanguage() index: 3 es-ES, 15 pt-PT, 20 pt-BR; the rest get English
    const lang = { 3: 'es', 15: 'pt', 20: 'pt' }[hmSetting.getLanguage()] || 'en'

    // ---- normal screen
    img(0, 0, F.bg)
    img(L.labelsAt[0], L.labelsAt[1], F.labels[lang])
    odometer()
    date(F.tag, F.slash, F.week[lang], NORMAL, L)

    status(L.bt, F.bt_off, hmUI.system_status.DISCONNECT)
    status(L.alarm, F.alarm, hmUI.system_status.CLOCK)
    status(L.dnd, F.dnd, hmUI.system_status.DISTURB)
    status(L.lock, F.lock, hmUI.system_status.LOCK)

    const invalid = { invalid_image: F.val_minus }
    value(L.batteryText, F.val, T.BATTERY)
    value(L.heartText, F.val, T.HEART, invalid)
    value(L.spo2Text, F.val, T.SPO2, invalid)
    value(L.stressText, F.val, T.STRESS, invalid)
    value(L.stepText, F.val, T.STEP)
    value(L.distText, F.val, T.DISTANCE, { dot_image: F.val_dot })
    value(L.temp, F.val, T.WEATHER_CURRENT, { negative_image: F.val_minus, ...invalid })
    value(L.calText, F.val, T.CAL)
    sleepHours(value(L.sleepText, F.val, undefined, { text: '0.0', dot_image: F.val_dot }))
    // for STAND (current.target) dot_image is the separator
    value(L.standText, F.val, T.STAND, { dot_image: F.val_slash })

    hmUI.createWidget(hmUI.widget.IMG_LEVEL, {
      x: L.weatherIcon[0],
      y: L.weatherIcon[1],
      image_array: F.weather,
      image_length: F.weather.length,
      type: T.WEATHER_CURRENT,
      show_level: NORMAL
    })

    click(L.click.heart, T.HEART)
    click(L.click.spo2, T.SPO2)
    click(L.click.stress, T.STRESS)
    click(L.click.weather, T.WEATHER_CURRENT)
    click(L.click.steps, T.STEP)
    click(L.click.cal, T.CAL)
    click(L.click.sleep, T.SLEEP)
    click(L.click.stand, T.STAND)

    // ---- always-on display: dimmed time, date and weekday on black
    img(0, 0, F.bg_aod, AOD)
    time(F.drum_aod, null, AOD, L.aod.hour, L.aod.minute)
    date(F.tag_aod, F.slash_aod, F.week_aod[lang], AOD, L.aod)
  }
})
